use kimi_switcher::login::{authorization_url,login_arguments};
#[test]fn accepts_only_official_authorization_url(){assert_eq!(authorization_url("Opening browser for Kimi device login: https://auth.kimi.com/device?user_code=TEST"),Some("https://auth.kimi.com/device?user_code=TEST".into()));assert!(authorization_url("https://auth.kimi.com.evil.invalid/device").is_none());assert!(authorization_url("https://user:pass@auth.kimi.com/device").is_none());assert!(authorization_url("http://auth.kimi.com/device").is_none());assert!(authorization_url("https://evil.invalid/?url=https://auth.kimi.com").is_none());}
#[test]fn login_region_is_a_separate_validated_argument(){assert_eq!(login_arguments("global").unwrap(),vec!["login","--region","global"]);assert!(login_arguments("global; echo secret").is_err());}
